<?php
require '/app/harness.php';
check('ACL editor requires complete explicit masks and numeric identities',function(){ $text="user::rwx\nuser:99:rwx\ngroup::r-x\nmask::r-x\nother::---\n";$canonical=zfsmACLCanonical($text);same($canonical,zfsmACLCanonical($canonical));same('r-x',array_values(array_filter(zfsmParsePosixACL($canonical),fn($e)=>$e['id']==='99'))[0]['effective']);foreach(["user::rwx\ngroup::r-x\n",$text."# owner: root\n",str_replace('99','nobody',$text)] as $invalid){try{zfsmACLCanonical($invalid);throw new LogicException('Expected rejection');}catch(InvalidArgumentException $e){}} });
check('ACL editor never enables unsupported types unsafe parents special modes or volumes',function(){ $p=['type'=>'filesystem','mounted'=>'yes','acltype'=>'posix','keystatus'=>'available'];same(null,zfsmACLEditIssue($p,true,0755,true));foreach([[$p,false,0755,true],[$p,true,01777,true],[$p,true,0755,false],[array_replace($p,['acltype'=>'nfsv4']),true,0755,true],[array_replace($p,['type'=>'volume']),true,0755,true],[array_replace($p,['mounted'=>'no']),true,0755,true]] as $args)same(true,is_string(zfsmACLEditIssue(...$args))); });
check('native masked ACL comments are verified then stripped from canonical write input',function(){ $native="user::rwx\nuser:99:rwx\t#effective:r-x\ngroup::r-x\nmask::r-x\nother::---\n";$canonical=zfsmACLCanonical($native,true);same(false,str_contains($canonical,'#'));same(true,str_contains($canonical,'user:99:rwx')); });
finishTests();
